/**
 * Shared palette exports backed by the exact Material 3 colors generated by
 * the Flutter app's `ColorScheme.fromSeed(seedColor: Colors.blueGrey)`.
 * Legacy key names are kept as aliases so existing screens keep working, while
 * new code can use the M3 role names directly.
 * @module src/constants/colors
 */
import {darkColors, lightColors as lightM3Colors, SEED_COLOR} from "./material-theme";

function toPalette(source) {
  return {
    ...source,
    // Legacy aliases used by existing screens/components.
    surfaceRaised: source.surfaceContainer,
    border: source.outlineVariant,
    textPrimary: source.onSurface,
    textSecondary: source.onSurfaceVariant,
    textMuted: source.onSurfaceVariant,
    accent: source.primary,
    accentCyan: source.error,
    danger: source.error,
    success: "#2E7D32",
    warning: "#B26A00",
  };
}

export const colors = toPalette(darkColors);
export const lightColorsPalette = toPalette(lightM3Colors);
export const lightColors = lightColorsPalette;
export const themes = {
  dark: colors,
  light: lightColorsPalette,
};

export const gradients = {
  // Retained for any legacy decorative use; the Flutter app itself uses flat
  // Material 3 surface colors rather than gradients.
  brand: [SEED_COLOR, SEED_COLOR],
};

export const spacing = {
  xs: 4,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 24,
  xxl: 32,
  xxxl: 48,
  xxxxl: 64,
};

export const radius = {
  sm: 8,
  md: 12,
  lg: 20,
  xl: 32,
  pill: 999,
};

export {typography, motion, SEED_COLOR} from "./material-theme";
